CREATE TABLE png_image (id INTEGER PRIMARY KEY CHECK(id=1), schema TEXT NOT NULL, width INTEGER NOT NULL, height INTEGER NOT NULL, bit_depth INTEGER NOT NULL, color_type INTEGER NOT NULL, interlace INTEGER NOT NULL CHECK(interlace IN (0,1)), has_palette INTEGER NOT NULL CHECK(has_palette IN (0,1)));
CREATE TABLE png_sample (id INTEGER PRIMARY KEY, image_id INTEGER NOT NULL REFERENCES png_image(id), ordinal INTEGER NOT NULL, value INTEGER NOT NULL CHECK(value BETWEEN 0 AND 65535));
CREATE TABLE png_palette_entry (id INTEGER PRIMARY KEY, image_id INTEGER NOT NULL REFERENCES png_image(id), ordinal INTEGER NOT NULL, red INTEGER NOT NULL, green INTEGER NOT NULL, blue INTEGER NOT NULL);
CREATE TABLE png_transparency (id INTEGER PRIMARY KEY CHECK(id=1), color_type INTEGER NOT NULL, first INTEGER NOT NULL, second INTEGER NOT NULL, third INTEGER NOT NULL);
CREATE TABLE png_alpha (id INTEGER PRIMARY KEY, image_id INTEGER NOT NULL REFERENCES png_image(id), ordinal INTEGER NOT NULL, value INTEGER NOT NULL CHECK(value BETWEEN 0 AND 255));
CREATE TABLE png_background (id INTEGER PRIMARY KEY CHECK(id=1), color_type INTEGER NOT NULL, first INTEGER NOT NULL, second INTEGER NOT NULL, third INTEGER NOT NULL);
CREATE TABLE png_gamma (id INTEGER PRIMARY KEY CHECK(id=1), value INTEGER NOT NULL);
CREATE TABLE png_chromaticities (id INTEGER PRIMARY KEY CHECK(id=1), white_x INTEGER NOT NULL, white_y INTEGER NOT NULL, red_x INTEGER NOT NULL, red_y INTEGER NOT NULL, green_x INTEGER NOT NULL, green_y INTEGER NOT NULL, blue_x INTEGER NOT NULL, blue_y INTEGER NOT NULL);
CREATE TABLE png_srgb (id INTEGER PRIMARY KEY CHECK(id=1), intent INTEGER NOT NULL);
CREATE TABLE png_physical_dims (id INTEGER PRIMARY KEY CHECK(id=1), ppu_x INTEGER NOT NULL, ppu_y INTEGER NOT NULL, unit_is_meter INTEGER NOT NULL CHECK(unit_is_meter IN (0,1)));
CREATE TABLE png_timestamp (id INTEGER PRIMARY KEY CHECK(id=1), year INTEGER NOT NULL, month INTEGER NOT NULL, day INTEGER NOT NULL, hour INTEGER NOT NULL, minute INTEGER NOT NULL, second INTEGER NOT NULL);
CREATE TABLE png_text (id INTEGER PRIMARY KEY, image_id INTEGER NOT NULL REFERENCES png_image(id), ordinal INTEGER NOT NULL, keyword TEXT NOT NULL, value TEXT NOT NULL, kind INTEGER NOT NULL, compressed INTEGER NOT NULL CHECK(compressed IN (0,1)), language_tag TEXT NOT NULL, translated_keyword TEXT NOT NULL);
CREATE TABLE png_ancillary_chunk (id INTEGER PRIMARY KEY, image_id INTEGER NOT NULL REFERENCES png_image(id), ordinal INTEGER NOT NULL, kind BLOB NOT NULL, after_raster INTEGER NOT NULL CHECK(after_raster IN (0,1)), data BLOB NOT NULL);
